-- Efek RGB hanya border
task.spawn(function()
	while true do
		local t = tick()
		local r = math.abs(math.sin(t))
		local g = math.abs(math.sin(t + 2))
		local b = math.abs(math.sin(t + 4))

		mainFrame.BorderColor3 = Color3.new(r, g, b)

		RunService.RenderStepped:Wait()
	end
end)


